flow.script:

package main

import (
    "fmt"
    "os"
    "sort"
    "host/vars"
)

func main() {
    header := "\n========== Final Pipeline Variables After While Loop =========="
    fmt.Println(header)
    fmt.Fprintln(os.Stdout, header)

    allVars := vars.GetAll()
    keys := make([]string, 0, len(allVars))
    for k := range allVars {
        keys = append(keys, k)
    }
    sort.Strings(keys)
    for _, name := range keys {
        line := fmt.Sprintf("  %-20s = %v", name, allVars[name])
        fmt.Println(line)
        fmt.Fprintln(os.Stdout, line)
    }
    footer := "================================================================"
    fmt.Println(footer)
    fmt.Fprintln(os.Stdout, footer)
}
